def base_of(name):
    return re.sub(r'\.\d{3}$', '', name)


def ensure_object_mode():
    if bpy.context.object and bpy.context.object.mode != 'OBJECT':
        bpy.ops.object.mode_set(mode='OBJECT')


def activate(obj):
    for o in bpy.context.view_layer.objects:
        o.select_set(False)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)


def is_source(o):
    return o is not None and o.type == 'ARMATURE' and all(n in o.data.bones for n in REQUIRED)


def find_source():
    ctx = bpy.context
    pool = [ctx.active_object] + list(ctx.selected_objects)
    for o in pool:
        if is_source(o):
            return o
    for o in ctx.scene.objects:
        if is_source(o):
            return o
    return None


def bound_meshes(arm):
    out = []
    for o in bpy.context.scene.objects:
        if o.type != 'MESH':
            continue
        if o.parent == arm or any(m.type == 'ARMATURE' and m.object == arm for m in o.modifiers):
            out.append(o)
    return out


def preserve_face_markers(src):
    """Keep FBX expression empties and unskinned eyes before empty cleanup."""
    if not is_source(src):
        return
    ensure_object_mode()
    top = src
    while top.parent is not None:
        top = top.parent
    imported = [top] + list(top.children_recursive)
    markers = [o for o in imported if o.type == 'EMPTY'
               and base_of(o.name).startswith(FAC_PREFIX)]
    eyes = [o for o in imported if o.type == 'MESH'
            and base_of(o.name).lower().startswith('bangboo_eyes')
            and not any(m.type == 'ARMATURE' and m.object not in (None, src)
                        for m in o.modifiers)]
    # The C++ FBX importer leaves expression markers as empties and the eye
    # atlas unskinned. Convert the markers without changing their world pose.
    if markers:
        transforms = [(base_of(o.name), src.matrix_world.inverted() @ o.matrix_world)
                      for o in markers]
        length = max((src.data.bones['Skin_Head'].head_local
                      - src.data.bones['Skin_Pelvis'].head_local).length * 0.1, 1e-4)
        active = bpy.context.view_layer.objects.active
        activate(src)
        bpy.ops.object.mode_set(mode='EDIT')
        bones = src.data.edit_bones
        for name, matrix in transforms:
            if name in bones:
                continue
            bone = bones.new(name)
            bone.head = (0.0, 0.0, 0.0)
            bone.tail = (0.0, length, 0.0)
            bone.matrix = matrix
            bone.parent = bones['Skin_Head']
            bone.use_deform = True
        bpy.ops.object.mode_set(mode='OBJECT')
        bpy.context.view_layer.objects.active = active
    for obj in eyes:
        world = obj.matrix_world.copy()
        obj.parent = src
        obj.matrix_world = world
    bpy.context.view_layer.update()


def collect_empties(src, meshes):
    roots = set()
    for o in [src] + list(meshes):
        top = o
        while top.parent is not None:
            top = top.parent
        roots.add(top)
    found = []
    for r in roots:
        for o in [r] + list(r.children_recursive):
            if o.type == 'EMPTY' and o not in found:
                found.append(o)
    return found


def pick_name(arm, meshes):
    name = None
    for m in meshes:
        mt = re.match(r'Bangboo_([A-Za-z]+)', base_of(m.name))
        if mt and mt.group(1) not in ('Eyes', 'Eye'):
            name = mt.group(1)
            break
    if not name:
        name = re.sub(r'[^A-Za-z0-9]+', '_', base_of(arm.name)).strip('_') or 'Bangboo'
    final = name
    i = 2
    while bpy.data.collections.get(final + '_Master') or bpy.data.objects.get(final + '_Rig'):
        final = '%s%d' % (name, i)
        i += 1
    return final


def used_groups(mesh_obj):
    names = {g.index: g.name for g in mesh_obj.vertex_groups}
    used = set()
    for v in mesh_obj.data.vertices:
        for g in v.groups:
            if g.weight > 0.0 and g.group in names:
                used.add(names[g.group])
    return used


def bone_world(arm, bone, posed=False):
    mw = arm.matrix_world @ (arm.pose.bones[bone.name].matrix if posed else bone.matrix_local)
    loc, rot, _ = mw.decompose()
    sc = arm.matrix_world.to_scale()
    length = bone.length * (abs(sc.x) + abs(sc.y) + abs(sc.z)) / 3.0
    return Matrix.Translation(loc) @ rot.to_matrix().to_4x4(), max(length, 1e-4)


def bake_face_bind_pose(src, meshes):
    """Keep the FBX eye bind correction when replacing its source armature."""
    bpy.context.view_layer.update()
    for obj in meshes:
        if not any(name.startswith(FAC_PREFIX) for name in used_groups(obj)):
            continue
        if not any(mod.type == 'ARMATURE' and mod.object == src for mod in obj.modifiers):
            continue
        if obj.data.users > 1:
            obj.data = obj.data.copy()
        to_mesh = obj.matrix_world.inverted() @ src.matrix_world
        to_arm = to_mesh.inverted()
        transforms = {
            group.index: to_mesh @ src.pose.bones[group.name].matrix
            @ src.data.bones[group.name].matrix_local.inverted() @ to_arm
            for group in obj.vertex_groups if group.name in src.data.bones
        }
        points = ([key.data for key in obj.data.shape_keys.key_blocks]
                  if obj.data.shape_keys else [obj.data.vertices])
        for vertex in obj.data.vertices:
            weights = [(transforms[group.group], group.weight) for group in vertex.groups
                       if group.group in transforms and group.weight > 0.0]
            total = sum(weight for _, weight in weights)
            if total:
                for coordinates in points:
                    point = coordinates[vertex.index]
                    original = point.co.copy()
                    point.co = sum((matrix @ original * weight for matrix, weight in weights), Vector()) / total
        obj.data.update()


def preserve_face_bind_rest(src):
    """Make the imported facial correction survive the wizard's pose reset."""
    preserve_face_markers(src)
    bpy.context.view_layer.update()
    matrices = {bone.name: src.pose.bones[bone.name].matrix.copy()
                for bone in src.data.bones if bone.name.startswith(FAC_PREFIX)}
    if not matrices:
        return
    bake_face_bind_pose(src, bound_meshes(src))
    activate(src)
    bpy.ops.object.mode_set(mode='EDIT')
    for name, matrix in matrices.items():
        src.data.edit_bones[name].matrix = matrix
    bpy.ops.object.mode_set(mode='OBJECT')
    for name in matrices:
        src.pose.bones[name].matrix_basis = Matrix.Identity(4)
    bpy.context.view_layer.update()


def bake_mesh(o):
    if o.data.users > 1:
        o.data = o.data.copy()
    mw = o.matrix_world.copy()
    o.parent = None
    o.matrix_world = Matrix.Identity(4)
    o.data.transform(mw, shape_keys=True)
    if mw.determinant() < 0:
        o.data.flip_normals()
    o.data.update()
    for m in [m for m in o.modifiers if m.type == 'ARMATURE']:
        o.modifiers.remove(m)


def islands_of(o):
    bm = bmesh.new()
    bm.from_mesh(o.data)
    bm.verts.ensure_lookup_table()
    seen = set()
    out = []
    for v in bm.verts:
        if v.index in seen:
            continue
        stack = [v]
        seen.add(v.index)
        comp = []
        while stack:
            x = stack.pop()
            comp.append(x.index)
            for e in x.link_edges:
                y = e.other_vert(x)
                if y.index not in seen:
                    seen.add(y.index)
                    stack.append(y)
        out.append(comp)
    bm.free()
    return out


def is_prop_name(name):
    for tok in re.split(r'[_ .]+', name.lower()):
        t = tok.rstrip('0123456789')
        if t in PROP_TOKENS or tok in PROP_TOKENS:
            return True
    return False


def island_centroids(o):
    verts = o.data.vertices
    out = []
    for comp in islands_of(o):
        c = Vector()
        for i in comp:
            c += verts[i].co
        out.append((comp, c / len(comp)))
    return out


def yz_fit(points, heads, side):
    if not points:
        return 0.0
    total = 0.0
    for p in points:
        total += min(((h.y - p.y) ** 2 + (h.z - p.z) ** 2) ** 0.5 + max(0.0, abs(h.x - p.x) - side) for h in heads)
    return total / len(points)


def align_eyes(o, fac_heads, pivots, tol):
    heads = list(fac_heads.values())
    if not heads:
        return
    cents = [c for _, c in island_centroids(o)]
    if not cents:
        return
    side = tol * 8.0
    best = yz_fit(cents, heads, side)
    if best <= tol:
        return
    hmin = Vector((min(h.x for h in heads), min(h.y for h in heads), min(h.z for h in heads)))
    hmax = Vector((max(h.x for h in heads), max(h.y for h in heads), max(h.z for h in heads)))
    hcen = (hmin + hmax) * 0.5
    choice = None
    for mode in (0, 1):
        if mode == 1 and best <= tol:
            break
        for rot in ROTATIONS:
            for pv in pivots:
                moved = [rot @ (c - pv) + pv for c in cents]
                shift = Vector()
                if mode == 1:
                    cmin = Vector((min(m.x for m in moved), min(m.y for m in moved), min(m.z for m in moved)))
                    cmax = Vector((max(m.x for m in moved), max(m.y for m in moved), max(m.z for m in moved)))
                    cc = (cmin + cmax) * 0.5
                    shift = Vector((0.0, hcen.y - cc.y, hcen.z - cc.z))
                score = yz_fit([m + shift for m in moved], heads, side)
                if score < best - 1e-6:
                    best = score
                    choice = (rot, pv, shift)
    if choice is None:
        return
    rot, pv, shift = choice
    mat = Matrix.Translation(pv + shift) @ rot.to_4x4() @ Matrix.Translation(-pv)
    o.data.transform(mat, shape_keys=True)
    o.data.update()


#binding falls back to nearest expression bone, now in full 3d so a left eye cant
#grab a bone sitting on the right side of the face
def bind_eyes(o, fac_heads):
    if not fac_heads:
        return
    if any(n in fac_heads for n in used_groups(o)):
        return
    for g in list(o.vertex_groups):
        o.vertex_groups.remove(g)
    groups = {n: o.vertex_groups.new(name=n) for n in fac_heads}
    verts = o.data.vertices
    for comp, c in island_centroids(o):
        best = min(fac_heads, key=lambda n: (fac_heads[n] - c).length)
        groups[best].add(comp, 1.0, 'REPLACE')


def seg_dist(p, a, b):
    ab = b - a
    d = ab.length_squared
    t = 0.0 if d < 1e-12 else max(0.0, min(1.0, (p - a).dot(ab) / d))
    return (a + ab * t - p).length


def bind_props(o, segs):
    if not segs or used_groups(o):
        return
    groups = {}
    for comp, c in island_centroids(o):
        best = min(segs, key=lambda n: seg_dist(c, segs[n][0], segs[n][1]))
        if best not in groups:
            groups[best] = o.vertex_groups.get(best) or o.vertex_groups.new(name=best)
        groups[best].add(comp, 1.0, 'REPLACE')


def add_props_toggle(o, arm):
    g = o.vertex_groups.get('_props_all') or o.vertex_groups.new(name='_props_all')
    g.add(list(range(len(o.data.vertices))), 1.0, 'REPLACE')
    mod = o.modifiers.new('Props Toggle', 'MASK')
    mod.mode = 'VERTEX_GROUP'
    mod.vertex_group = '_props_all'
    # Hide the source geometry before Extra FX/outlines create instances;
    # a Mask at the end cannot remove geometry inside those instances.
    nodes_index = next((i for i, m in enumerate(o.modifiers) if m.type == 'NODES'), None)
    if nodes_index is not None:
        with bpy.context.temp_override(object=o, active_object=o):
            bpy.ops.object.modifier_move_to_index(modifier=mod.name, index=nodes_index)
    fc = mod.driver_add('invert_vertex_group')
    drv = fc.driver
    drv.type = 'AVERAGE'
    var = drv.variables.new()
    var.name = 'vis'
    var.type = 'SINGLE_PROP'
    var.targets[0].id_type = 'ARMATURE'
    var.targets[0].id = arm
    var.targets[0].data_path = 'collections_all["Props"].is_visible'
    for m in list(fc.modifiers):
        fc.modifiers.remove(m)
    gen = fc.modifiers.new('GENERATOR')
    gen.coefficients = (1.0, -1.0)


def rename_groups(o):
    for g in list(o.vertex_groups):
        if g.name not in CORE:
            continue
        target = 'DEF-' + CORE[g.name]
        existing = o.vertex_groups.get(target)
        if existing is None:
            g.name = target
            continue
        for v in o.data.vertices:
            for vg in v.groups:
                if vg.group == g.index and vg.weight > 0.0:
                    existing.add([v.index], vg.weight, 'ADD')
        o.vertex_groups.remove(g)


def foot_layout(foot_head, shin_len, side):
    f = foot_head
    ball = Vector((f.x + 0.030 * shin_len * side, f.y - 0.710 * shin_len, f.z - 0.230 * shin_len))
    tip = Vector((ball.x, f.y - 1.074 * shin_len, ball.z))
    heel_h = Vector((f.x + 0.043 * shin_len * side, f.y + 0.436 * shin_len, f.z - 0.352 * shin_len))
    heel_t = heel_h + Vector((0.432 * shin_len * side, 0.0, 0.0))
    return ball, tip, heel_h, heel_t


def mirror_z(name, vec):
    v = Vector(vec)
    if name.endswith('.R'):
        v.x = -v.x
    return v


def build_metarig(name, P):
    bpy.context.scene.cursor.location = (0.0, 0.0, 0.0)
    bpy.ops.object.armature_basic_human_metarig_add()
    meta = bpy.context.active_object
    meta.name = name + '_metarig'
    meta.location = (0.0, 0.0, 0.0)
    meta.rotation_euler = (0.0, 0.0, 0.0)
    meta.scale = (1.0, 1.0, 1.0)
    bpy.ops.object.mode_set(mode='EDIT')
    eb = meta.data.edit_bones
    for n in ('breast.L', 'breast.R'):
        if n in eb:
            eb.remove(eb[n])
    pel = P['Skin_Pelvis']
    sp = P['Skin_Spine']
    hd = P['Skin_Head']
    v = hd - sp
    head_len = max((hd - pel).length * 0.89, 1e-3)
    chain = [pel, sp, sp + v * 0.183, sp + v * 0.375, sp + v * 0.83, sp + v * 0.915, hd, hd + Vector((0.0, 0.0, head_len))]
    spine_names = ['spine', 'spine.001', 'spine.002', 'spine.003', 'spine.004', 'spine.005', 'spine.006']
    place = {}
    for i, n in enumerate(spine_names):
        place[n] = (chain[i], chain[i + 1])
    for s, side in (('L', 1.0), ('R', -1.0)):
        cl = P.get('Skin_Clavicle_' + s)
        ua = P['Skin_UpperArm_' + s]
        fa = P.get('Skin_Forearm_' + s)
        hn = P.get('Skin_Hand_' + s)
        if cl is None:
            cl = Vector((sp.x + (ua.x - sp.x) * 0.6, ua.y, ua.z))
        if fa is None:
            fa = ua + Vector((0.0, 0.0, -head_len * 0.4))
        if hn is None:
            hn = fa + (fa - ua) * 0.85
        place['shoulder.' + s] = (cl, ua)
        place['upper_arm.' + s] = (ua, fa)
        place['forearm.' + s] = (fa, hn)
        place['hand.' + s] = (hn, hn + (hn - fa))
        th = P['Skin_Thigh_' + s]
        ca = P.get('Skin_Calf_' + s)
        ft = P.get('Skin_Foot_' + s)
        if ca is None:
            ca = th + (Vector((th.x, th.y, 0.0)) - th) * 0.6
        if ft is None:
            ft = ca + (ca - th) * 0.55
        shin_len = max((ft - ca).length, 1e-3)
        ball, tip, heel_h, heel_t = foot_layout(ft, shin_len, side)
        place['thigh.' + s] = (th, ca)
        place['shin.' + s] = (ca, ft)
        place['foot.' + s] = (ft, ball)
        place['toe.' + s] = (ball, tip)
        place['heel.02.' + s] = (heel_h, heel_t)
        tx = abs(th.x - pel.x)
        place['pelvis.' + s] = (pel, pel + Vector((1.86 * tx * side, -0.354 * tx, 0.606 * tx)))
    connected = {b.name: b.use_connect for b in eb}
    for n in eb:
        n.use_connect = False
    for n, (h, t) in place.items():
        if n in eb:
            b = eb[n]
            b.head = h
            b.tail = t
    for b in eb:
        key = b.name[:-2] + '.L' if b.name.endswith('.R') else b.name
        if key in ZAXIS:
            b.align_roll(mirror_z(b.name, ZAXIS[key]))
    for b in eb:
        if connected.get(b.name) and b.parent:
            b.head = b.parent.tail.copy()
            b.use_connect = True
    bpy.ops.object.mode_set(mode='OBJECT')
    arm = meta.data
    if 'Face' not in arm.collections_all:
        arm.collections.new('Face')
    for c in arm.collections_all:
        if c.name in ROWS:
            c['rigify_ui_row'] = ROWS[c.name][0]
            c['rigify_color_set_id'] = ROWS[c.name][1]
    return meta, head_len


def generate(meta):
    activate(meta)
    meta.data.rigify_target_rig = None
    bpy.ops.pose.rigify_generate()
    rig = meta.data.rigify_target_rig
    if rig is None:
        rig = bpy.context.view_layer.objects.active
    return rig


def make_widget(name, verts, edges, coll):
    me = bpy.data.meshes.new(name)
    me.from_pydata(verts, edges, [])
    me.update()
    ob = bpy.data.objects.new(name, me)
    coll.objects.link(ob)
    return ob


def add_loop(verts, edges, pts):
    start = len(verts)
    verts.extend(pts)
    n = len(pts)
    for i in range(n):
        edges.append((start + i, start + (i + 1) % n))


def rect(x0, z0, x1, z1):
    return [(x0, 0.0, z0), (x1, 0.0, z0), (x1, 0.0, z1), (x0, 0.0, z1)]


def panel_shape(slots):
    k = 1.9
    n = len(slots)
    verts = []
    edges = []
    add_loop(verts, edges, rect(-2.45, -0.62, 2.45, n - 1 + 0.62))
    add_loop(verts, edges, rect(-1.2, -0.92, 1.2, -0.62))
    for i, expr in enumerate(slots):
        z = float(i)
        add_loop(verts, edges, [(-2.45, 0.0, z - 0.08), (-2.3, 0.0, z), (-2.45, 0.0, z + 0.08)])
        add_loop(verts, edges, [(2.45, 0.0, z - 0.08), (2.3, 0.0, z), (2.45, 0.0, z + 0.08)])
        if i < n - 1:
            edges.append((len(verts), len(verts) + 1))
            verts.extend([(-1.9, 0.0, z + 0.5), (1.9, 0.0, z + 0.5)])
        loops = [ICONS.get(expr, ICON_DEFAULT)]
        if expr in ICON_EXTRA:
            loops.append(ICON_EXTRA[expr])
        for loop in loops:
            for sx in (1.0, -1.0):
                pts = [(x * k * sx, 0.0, z - u * k) for x, u in loop]
                if sx < 0:
                    pts.reverse()
                add_loop(verts, edges, pts)
    return verts, edges


def macro_shape():
    verts = []
    edges = []
    add_loop(verts, edges, rect(-2.15, -0.47, 2.15, 0.47))
    add_loop(verts, edges, [(-3.05, 0.0, -0.22), (-2.6, 0.0, 0.0), (-3.05, 0.0, 0.22)])
    add_loop(verts, edges, [(3.05, 0.0, -0.22), (2.6, 0.0, 0.0), (3.05, 0.0, 0.22)])
    return verts, edges


def set_color(bone, cols):
    bone.color.palette = 'CUSTOM'
    bone.color.custom.normal = cols[0]
    bone.color.custom.select = cols[1]
    bone.color.custom.active = cols[2]


def ensure_coll(arm, name):
    c = arm.collections_all.get(name)
    if c is None:
        c = arm.collections.new(name)
    return c


def link_only(obj, coll):
    for c in list(obj.users_collection):
        c.objects.unlink(obj)
    coll.objects.link(obj)


# pelvis1 n pelvis2 r the same box as pelvis just scaled, so they just alias
def shape_data(key):
    key = WIDGET_ALIAS.get(key, key)
    return WIDGET_SHAPES.get(key)


def widget_entry(bone_name):
    if bone_name.startswith(WIDGET_SKIP):
        return None
    for pat, key, size, cap, anchor, rot in WIDGET_MAP:
        if re.search(pat, bone_name):
            return key, size, cap, anchor, rot
    return None


def bone_widget(rig_name, pb, key, size, cap, anchor, rot, coll):
    data = shape_data(key)
    if data is None:
        return None
    verts, edges = data
    length = max(pb.bone.length, 1e-5)
    if cap > 0.0:
        size = min(size, length * cap)
    size *= WIDGET_SCALE * WIDGET_OVERRIDE.get(pb.name, 1.0)
    # .R side gets x flipped so the art reads the same on both arms/legs
    sx = -1.0 if pb.name.endswith('.R') else 1.0
    slide = anchor * length
    spin = Matrix.Identity(3)
    if any(rot):
        spin = Euler([radians(a) for a in rot], 'XYZ').to_matrix()
    pts = []
    for v in verts:
        p = spin @ Vector(v)
        pts.append((p.x * size * sx, p.y * size + slide, p.z * size))
    wname = 'WGT-%s_%s' % (rig_name, pb.name)
    old = bpy.data.objects.get(wname)
    if old is not None:
        bpy.data.objects.remove(old, do_unlink=True)
    return make_widget(wname, pts, [tuple(e) for e in edges], coll)


def assign_shape(pb, ob):
    pb.custom_shape = ob
    pb.use_custom_shape_bone_size = False
    if hasattr(pb, 'custom_shape_wire_width'):
        pb.custom_shape_wire_width = 1.6
    pb.custom_shape_scale_xyz = (1.0, 1.0, 1.0)
    pb.custom_shape_translation = (0.0, 0.0, 0.0)
    pb.custom_shape_rotation_euler = (0.0, 0.0, 0.0)


#one mesh per bone, size is baked in so bone size is off and scale stays 1
#means u can still nudge any single control by hand after n nothing fights u
def apply_widgets(rig, coll, rig_name, unit):
    used = []
    for pb in rig.pose.bones:
        entry = widget_entry(pb.name)
        if entry is None:
            continue
        key, size, cap, anchor, rot = entry
        ob = bone_widget(rig_name, pb, key, size * unit, cap, anchor, rot, coll)
        if ob is None:
            continue
        assign_shape(pb, ob)
        used.append(pb.name)
    return used


#rounded drum, bone points up so the floor plane is x/z
#bow sags the middle of the band down n leaves the two side tips up, so looking at
#the boo from the front the hips curve downwards like a bowl
def round_box_shape(w, d, h, r, segs=5, bow=0.0):
    hx = w * 0.5
    hz = d * 0.5
    r = max(min(r, hx * 0.95, hz * 0.95), 0.0)
    ring = []
    for cx, cz, a0 in ((hx - r, hz - r, 0.0), (-(hx - r), hz - r, 90.0),
                       (-(hx - r), -(hz - r), 180.0), ((hx - r), -(hz - r), 270.0)):
        for i in range(segs):
            a = radians(a0 + 90.0 * i / segs)
            ring.append((cx + r * cos(a), cz + r * sin(a)))
    verts = []
    edges = []
    n = len(ring)
    for sign in (1.0, -1.0):
        base = len(verts)
        for x, z in ring:
            t = min(abs(x) / hx, 1.0) if hx > 1e-9 else 1.0
            verts.append((x, sign * h * 0.5 - bow * (1.0 - t * t), z))
        for i in range(n):
            edges.append((base + i, base + (i + 1) % n))
    step = max(n // 8, 1)
    for i in range(0, n, step):
        edges.append((i, n + i))
    return verts, edges


#how wide a widget actually ends up in the viewport, mesh bounds times whatever
#scaling that bone has on it
def shape_width(pb):
    ob = pb.custom_shape
    if ob is None or not len(ob.data.vertices):
        return None
    xs = [v.co.x for v in ob.data.vertices]
    zs = [v.co.z for v in ob.data.vertices]
    w = max(max(xs) - min(xs), max(zs) - min(zs))
    s = abs(pb.custom_shape_scale_xyz[0])
    if pb.use_custom_shape_bone_size:
        s *= pb.bone.length
    return w * s


#lift goes along the bone but bones point whichever way they want, so check which
#end of the bone is actually up in the world first
def lift_sign(pb):
    try:
        return 1.0 if pb.bone.y_axis.z >= 0.0 else -1.0
    except AttributeError:
        return 1.0


def body_widget(rig_name, pb, w, d, h, coll, bow=0.0, lift=0.0, segs=5):
    verts, edges = round_box_shape(w, d, h, min(w, d) * 0.3, segs=segs, bow=bow)
    if lift:
        off = lift * lift_sign(pb)
        verts = [(x, y + off, z) for x, y, z in verts]
    wname = 'WGT-%s_%s' % (rig_name, pb.name)
    old = bpy.data.objects.get(wname)
    if old is not None:
        bpy.data.objects.remove(old, do_unlink=True)
    return make_widget(wname, verts, edges, coll)


def theme_role(bone_name):
    for pat, role in THEME_MAP:
        if re.search(pat, bone_name):
            return role
    return None


#walks the 20 theme sets n picks the one sitting closest to the hue we asked for,
#skipping the washed out n dark ones so we get a punchy one
def theme_set_by_hue(hue, fallback):
    try:
        sets = bpy.context.preferences.themes[0].bone_color_sets
    except Exception:
        return fallback
    best = None
    for i, cs in enumerate(sets):
        c = cs.normal
        h, s, v = colorsys.rgb_to_hsv(c[0], c[1], c[2])
        if s < 0.45 or v < 0.5:
            continue
        d = abs(h - hue)
        d = min(d, 1.0 - d)
        score = d - 0.1 * s - 0.1 * v
        if best is None or score < best[0]:
            best = (score, i)
    return 'THEME%02d' % (best[1] + 1) if best else fallback


#rigify writes its colors on the POSE bone which beats the armature bone, so both
#levels gotta be set or u just keep seeing rigifys red n yellow lol
def apply_theme(rig, props_bones):
    arm = rig.data
    picked = dict(THEME)
    for role, val in THEME.items():
        if isinstance(val, str) and val in THEME_BY_HUE:
            hue, fallback = THEME_BY_HUE[val]
            picked[role] = theme_set_by_hue(hue, fallback)
            print('bangboo theme: %s -> %s' % (role, picked[role]))
    for pb in rig.pose.bones:
        if pb.name in THEME_KEEP:
            continue
        role = 'prop' if pb.name in props_bones else theme_role(pb.name)
        if role is None:
            if pb.custom_shape is None:
                continue
            role = 'body'
        pal = picked[role]
        b = arm.bones.get(pb.name)
        if isinstance(pal, str):
            pb.color.palette = pal
            if b is not None:
                b.color.palette = pal
        else:
            set_color(pb, pal)
            if b is not None:
                set_color(b, pal)


#u only wanna see the widgets, so any control left with a plain bone shape gets hidden
#props keep their bones tho cause thats how u grab em
def hide_bare_bones(rig, props_bones):
    hidden = []
    for b in rig.data.bones:
        if b.name in props_bones:
            b.hide = False
            continue
        pb = rig.pose.bones.get(b.name)
        if pb is not None and pb.custom_shape is None and not b.hide:
            b.hide = True
            hidden.append(b.name)
    for n in HIDE_BONES:
        if n in rig.data.bones:
            rig.data.bones[n].hide = True
    return hidden


def patch_layers_ui(rig):
    rig_id = rig.data.get('rig_id')
    if not rig_id:
        return False
    hit = False
    for txt in bpy.data.texts:
        body = txt.as_string()
        if 'class RigLayers' not in body or rig_id not in body:
            continue
        #eat rigifys class up to whatever starts at column 0 next
        new = re.sub(r'class RigLayers\(bpy\.types\.Panel\):\n.*?(?=\n[^\s#]|\Z)',
                     lambda m: LAYERS_SOLO_UI.rstrip('\n') + '\n\n', body, count=1, flags=re.S)
        if new == body:
            continue
        txt.clear()
        txt.write(new)
        hit = True
    #swap it live too, otherwise u gotta reload the file to see the stars lol
    old = getattr(bpy.types, 'VIEW3D_PT_rig_layers_' + rig_id, None)
    if old is not None:
        try:
            bpy.utils.unregister_class(old)
        except RuntimeError:
            pass
    ns = {'bpy': bpy, 'rig_id': rig_id}
    exec(LAYERS_SOLO_UI, ns)
    bpy.utils.register_class(ns['RigLayers'])
    return hit


def find_layer(layer, coll):
    if layer.collection == coll:
        return layer
    for ch in layer.children:
        r = find_layer(ch, coll)
        if r:
            return r
    return None


def organize_bangboo_collections(rig, context=None, scene=None):
    """Keep a Bangboo and its light together, with one excluded helper collection."""
    context = context or bpy.context
    scene = scene or context.scene
    if not rig or rig.type != 'ARMATURE' or not rig.data.get('bangboo_widget_unit'):
        return None
    master = rig.get('bangboo_character_collection')
    if not isinstance(master, bpy.types.Collection):
        # Older generated files have the rig inside <Name>_Rigs, below their master.
        direct = list(rig.users_collection)
        rig_subcollections = [c for c in direct if c.name.endswith('_Rigs')]
        master = next((c for c in bpy.data.collections
                       if any(child in rig_subcollections for child in c.children)), None)
        if master is None:
            master = next((c for c in direct if c != scene.collection), None)
        if master is None:
            master = bpy.data.collections.new(rig.name.removesuffix('Rig'))
            scene.collection.children.link(master)
    rig['bangboo_character_collection'] = master
    name = rig.get('gacha_character') or master.name.removesuffix('_Master')

    owned_collections = set()
    def visit(coll):
        for child in coll.children:
            owned_collections.add(child)
            visit(child)
    visit(master)
    owned = set(master.all_objects)
    owned.add(rig)
    shapes = {p.custom_shape for p in rig.pose.bones if p.custom_shape}
    shared_shapes = {p.custom_shape for other in bpy.data.objects
                     if other.type == 'ARMATURE' and other != rig
                     for p in other.pose.bones if p.custom_shape}
    owned.update(shapes)
    for ob in bpy.data.objects:
        parent = ob.parent
        while parent:
            if parent == rig:
                owned.add(ob)
                break
            parent = parent.parent
    models = {ob for ob in owned if ob.type == 'MESH' and ob not in shapes
              and any(m.type == 'ARMATURE' and m.object == rig for m in ob.modifiers)}
    # Head-driver and colour-picker targets can live in the template's lights/WGTS.
    pending = list(owned)
    inspected = set()
    while pending:
        ob = pending.pop()
        if ob in inspected:
            continue
        inspected.add(ob)
        for modifier in ob.modifiers:
            if modifier.type == 'NODES':
                try:
                    inputs = list(modifier.items())
                except TypeError:  # Blender 5.2 stores sockets in properties.inputs.
                    inputs = []
                properties = getattr(modifier, 'properties', None)
                sockets = getattr(properties, 'inputs', None)
                if sockets is not None and modifier.node_group:
                    for item in modifier.node_group.interface.items_tree:
                        if item.item_type == 'SOCKET' and item.in_out == 'INPUT' and item.socket_type == 'NodeSocketObject':
                            socket = getattr(sockets, item.identifier, None)
                            if socket is not None:
                                inputs.append((item.identifier, socket.value))
                for _, value in inputs:
                    if isinstance(value, bpy.types.Object) and value.type in ('MESH', 'EMPTY', 'ARMATURE') and value not in owned:
                        owned.add(value)
                        pending.append(value)
    widgets = next((c for c in owned_collections if c.name.startswith('WGTS_')), None)
    if widgets is None:
        widgets = bpy.data.collections.new('WGTS_' + name)
    else:
        widgets.name = 'WGTS_' + name
    owned_collections.add(widgets)
    # Remove duplicate links left by Rigify, without touching other characters.
    for parent in [scene.collection] + list(bpy.data.collections):
        if parent != master and widgets.name in parent.children:
            parent.children.unlink(widgets)
    if widgets.name not in master.children:
        master.children.link(widgets)

    old_object_collections = {c for ob in owned for c in ob.users_collection}
    for ob in owned:
        is_light = ob.name.startswith(('Light Direction', 'Main Light Direction'))
        target = master if ob == rig or ob in models or is_light else widgets
        if ob in shared_shapes:
            if ob.name not in target.objects:
                target.objects.link(ob)
        else:
            link_only(ob, target)
        if is_light:
            ob.hide_viewport = False
        if target == widgets:
            ob.hide_render = True
    # Dissolve only emptied collections created for this Bangboo.
    collections_before_cleanup = set(owned_collections)
    for coll in sorted(owned_collections - {widgets}, key=lambda c: c.name):
        for ob in list(coll.objects):
            if ob in shared_shapes:
                if ob.name not in widgets.objects:
                    widgets.objects.link(ob)
                coll.objects.unlink(ob)
            else:
                link_only(ob, widgets)
    changed = True
    while changed:
        changed = False
        for coll in list(owned_collections - {widgets}):
            if not coll.objects and not coll.children:
                owned_collections.remove(coll)
                bpy.data.collections.remove(coll)
                changed = True
    for coll in old_object_collections - collections_before_cleanup - {master, widgets}:
        if coll != scene.collection and not coll.objects and not coll.children:
            bpy.data.collections.remove(coll)
    widgets.hide_render = True
    widgets.hide_select = True
    widgets.hide_viewport = True
    default_collection = scene.collection.children.get('Collection')
    if default_collection and not default_collection.objects and not default_collection.children:
        bpy.data.collections.remove(default_collection)
    for layer in scene.view_layers:
        widget_layer = find_layer(layer.layer_collection, widgets)
        if widget_layer:
            widget_layer.exclude = True
    return master


def run(src=None):
    ensure_object_mode()
    bpy.context.view_layer.update()
    if src is None:
        src = find_source()
    if not is_source(src):
        raise RuntimeError('No Bangboo armature found (needs Skin_Pelvis / Skin_Head / limb bones)')
    preserve_face_markers(src)
    if 'rigify' not in bpy.context.preferences.addons:
        addon_utils.enable('rigify', default_set=True)
    meshes = bound_meshes(src)
    empties = collect_empties(src, meshes)
    import_collections = {c.name for o in [src] + meshes + empties for c in o.users_collection}
    name = pick_name(src, meshes)
    bake_face_bind_pose(src, meshes)
    bones = src.data.bones
    P = {n: src.matrix_world @ bones[n].head_local for n in CORE if n in bones}
    fac = {}
    for b in bones:
        if b.name.startswith(FAC_PREFIX):
            fac[b.name] = bone_world(src, b, posed=True)
    for o in meshes:
        bake_mesh(o)
    fac_heads = {n: m.translation.copy() for n, (m, _) in fac.items()}
    used = {o: used_groups(o) for o in meshes}
    eyes = [o for o in meshes if 'eye' in base_of(o.name).lower() or any(g in fac for g in used[o])]
    head_size = max((P['Skin_Head'] - P['Skin_Pelvis']).length * 0.89, 1e-3)
    pivots = [src.matrix_world.translation.copy(), P['Skin_Head'].copy(), P['Skin_Pelvis'].copy()]
    for o in eyes:
        #the auto aligner brute forces rotations n it was mangling eyes that were
        #already fine, so its off by default now. flip it on if ur eye mesh imports sideways
        if EYE_AUTOFIX and not any(n in fac_heads for n in used[o]):
            align_eyes(o, fac_heads, pivots, head_size * 0.06)
        bind_eyes(o, fac_heads)
        used[o] = used_groups(o)
    body = [o for o in meshes if o not in eyes and any(g in CORE for g in used[o])]
    props = [o for o in meshes if o not in eyes and o not in body]
    all_used = set()
    for o in meshes:
        all_used |= used[o]
    core_anc = set()
    for n in CORE:
        if n in bones:
            x = bones[n].parent
            while x is not None:
                if x.name not in CORE:
                    core_anc.add(x.name)
                x = x.parent

    def prop_chain(b):
        x = b
        while x is not None and x.name not in CORE:
            if is_prop_name(x.name):
                return True
            x = x.parent
        return False

    prop_set = set()
    phys_set = set()
    for b in bones:
        if b.name in CORE or b.name.startswith(FAC_PREFIX):
            continue
        if b.name in core_anc:
            if is_prop_name(b.name):
                prop_set.add(b.name)
            continue
        if prop_chain(b):
            prop_set.add(b.name)
        elif b.name in all_used:
            x = b
            while x is not None and x.name not in CORE and x.name not in core_anc:
                phys_set.add(x.name)
                x = x.parent
    phys_set -= prop_set
    keep = prop_set | phys_set
    extras = {}
    for b in bones:
        if b.name in keep:
            par = b.parent
            while par is not None and par.name not in CORE and par.name not in keep:
                par = par.parent
            extras[b.name] = (bone_world(src, b), par.name if par else None, 'Props' if b.name in prop_set else 'Physics')
    meta, head_len = build_metarig(name, P)
    rig = generate(meta)
    rig_obj_name = rig.name
    wgt_coll = meta.data.rigify_widgets_collection if hasattr(meta.data, 'rigify_widgets_collection') else None
    if wgt_coll is None:
        wgt_coll = bpy.data.collections.get('WGTS_' + rig_obj_name)
    meta_data = meta.data
    bpy.data.objects.remove(meta, do_unlink=True)
    if meta_data.users == 0:
        bpy.data.armatures.remove(meta_data)
    rig.name = name + '_Rig'
    arm = rig.data
    for control in ('upper_arm_parent.L', 'upper_arm_parent.R',
                    'thigh_parent.L', 'thigh_parent.R'):
        rig.pose.bones[control]['IK_Stretch'] = 0.0
    activate(rig)
    bpy.ops.object.mode_set(mode='EDIT')
    eb = arm.edit_bones
    face_c = ensure_coll(arm, 'Face')
    expr_c = ensure_coll(arm, 'Face (Expressions)')
    phys_c = ensure_coll(arm, 'Physics')
    props_c = ensure_coll(arm, 'Props')
    fav_c = ensure_coll(arm, 'Favorites')
    head_def = 'DEF-spine.006' if 'DEF-spine.006' in eb else 'root'
    for n, (m, length) in fac.items():
        b = eb.new(n)
        b.head = (0.0, 0.0, 0.0)
        b.tail = (0.0, length, 0.0)
        b.matrix = m
        b.parent = eb[head_def]
        b.use_deform = True
        expr_c.assign(b)
    for n, ((m, length), par, kind) in extras.items():
        b = eb.new(n)
        b.head = (0.0, 0.0, 0.0)
        b.tail = (0.0, length, 0.0)
        b.matrix = m
        b.use_deform = True
        (props_c if kind == 'Props' else phys_c).assign(b)
    for n, ((m, length), par, kind) in extras.items():
        if par is None:
            eb[n].parent = eb['root']
        elif par in CORE:
            target = 'DEF-' + CORE[par]
            eb[n].parent = eb[target] if target in eb else eb['root']
        else:
            eb[n].parent = eb[par]
    slots = sorted([n[len(FAC_PREFIX):] for n in fac], key=lambda e: (ORDER.index(e) if e in ORDER else len(ORDER), e))
    box_min = Vector((1e9, 1e9, 1e9))
    box_max = Vector((-1e9, -1e9, -1e9))
    for o in body + eyes:
        for v in o.data.vertices:
            c = o.matrix_world @ v.co
            box_min = Vector(map(min, box_min, c))
            box_max = Vector(map(max, box_max, c))
    if box_max.x < box_min.x:
        box_max = P['Skin_Head'] + Vector((head_len, head_len, head_len))
    step = head_len * 0.22
    hd = P['Skin_Head']
    origin = Vector((box_max.x + step * 3.6, hd.y, hd.z + head_len * 0.64))
    panel = eb.new('Face_Panel')
    panel.head = origin
    panel.tail = origin + Vector((0.0, -step, 0.0))
    panel.align_roll(Vector((0.0, 0.0, -1.0)))
    panel.parent = eb[head_def]
    panel.use_deform = False
    macro = eb.new('CTR_macro')
    macro.head = origin
    macro.tail = origin + Vector((0.0, -step, 0.0))
    macro.align_roll(Vector((0.0, 0.0, -1.0)))
    macro.parent = panel
    macro.use_deform = False
    face_c.assign(panel)
    face_c.assign(macro)
    segs = {n: (eb[n].head.copy(), eb[n].tail.copy()) for n in extras if extras[n][2] == 'Props'}
    for n in FAVORITES:
        if n in eb:
            fav_c.assign(eb[n])
    bpy.ops.object.mode_set(mode='OBJECT')
    if wgt_coll is not None:
        wgt_coll.name = name + '_WGTS_Rig'
    else:
        wgt_coll = bpy.data.collections.new(name + '_WGTS_Rig')
    if slots:
        pv, pe = panel_shape(slots)
        w_panel = make_widget('WGT-%s_face_panel' % name, pv, pe, wgt_coll)
        mv, me = macro_shape()
        w_macro = make_widget('WGT-%s_face_macro' % name, mv, me, wgt_coll)
        pb_panel = rig.pose.bones['Face_Panel']
        pb_macro = rig.pose.bones['CTR_macro']
        pb_panel.custom_shape = w_panel
        pb_macro.custom_shape = w_macro
        pb_panel.rotation_mode = 'QUATERNION'
        pb_macro.rotation_mode = 'QUATERNION'
        set_color(arm.bones['Face_Panel'], PANEL_COLOR)
        set_color(arm.bones['CTR_macro'], MACRO_COLOR)
        pb_macro.lock_location = (True, True, False)
        pb_macro.lock_rotation = (True, True, True)
        pb_macro.lock_rotation_w = True
        pb_macro.lock_scale = (True, True, True)
        n = len(slots)
        lim = pb_macro.constraints.new('LIMIT_LOCATION')
        lim.owner_space = 'LOCAL'
        lim.use_min_z = True
        lim.use_max_z = True
        lim.min_z = 0.0
        lim.max_z = step * (n - 1)
        lim.use_transform_limit = True
        act = bpy.data.actions.new(name + '_Face_Panel')
        if hasattr(act, 'id_root'):
            act.id_root = 'OBJECT'
        act.use_fake_user = True
        names = [FAC_PREFIX + e for e in slots]
        base = names[0]
        rest = {b: arm.bones[b].matrix_local for b in names}

        def local_delta(bone, world_target):
            m = rest[bone]
            return m.to_3x3().inverted() @ (world_target - m.translation)

        # Blender 5 uses layered actions; bind their slot to each Action
        # constraint explicitly so the expression selector evaluates correctly.
        if hasattr(act, 'slots'):
            slot = act.slots.new('OBJECT', rig.name)
            layer = act.layers.new('Expressions')
            strip = layer.strips.new(type='KEYFRAME')
            channelbag = strip.channelbag(slot, ensure=True)
            fcurves = channelbag.fcurves
        else:
            slot = None
            fcurves = act.fcurves
        for b in names:
            curves = [fcurves.new('pose.bones["%s"].location' % b, index=i) for i in range(3)]
            for j, shown in enumerate(names):
                if b == base:
                    d = Vector() if j == 0 else local_delta(b, rest[shown].translation)
                else:
                    d = local_delta(b, rest[base].translation) if b == shown else Vector()
                for i in range(3):
                    kp = curves[i].keyframe_points.insert(2.0 * j, d[i], options={'FAST'})
                    kp.interpolation = 'CONSTANT'
            for c in curves:
                for kp in c.keyframe_points:
                    kp.interpolation = 'CONSTANT'
                c.update()
        for b in names:
            pb = rig.pose.bones[b]
            con = pb.constraints.new('ACTION')
            con.target = rig
            con.subtarget = 'CTR_macro'
            con.transform_channel = 'LOCATION_Z'
            con.target_space = 'LOCAL'
            con.action = act
            if slot is not None:
                con.action_slot = slot
            con.frame_start = 0
            con.frame_end = 2 * n
            con.min = -0.5 * step
            con.max = (n - 0.5) * step
            con.mix_mode = 'BEFORE_SPLIT'
        arm['bangboo_face_slots'] = ','.join(slots)
    #unit = how tall the boo actually is, everything scales off this
    #bbox can come out junk if theres no mesh so fall back to head size
    unit = box_max.z - box_min.z
    if not 1e-4 < unit < 1e6:
        unit = head_len * 2.2
    arm['bangboo_widget_unit'] = unit
    apply_widgets(rig, wgt_coll, name, unit)

    for bn, (sc, tr, ref) in SHAPE_TWEAKS.items():
        pb = rig.pose.bones.get(bn)
        if pb is None:
            continue
        ratio = pb.bone.length / ref if ref > 0 else 1.0
        pb.custom_shape_scale_xyz = sc
        pb.custom_shape_translation = Vector(tr) * ratio

    #torso has to be sized first, hips gets measured against it
    #bbox x counts the arms sticking out so depth is the honest number to fall back on
    body_d = max(box_max.y - box_min.y, unit * 0.25)
    hips_pb = rig.pose.bones.get('hips')
    torso_pb = rig.pose.bones.get('torso')
    ref_w = shape_width(torso_pb) if torso_pb is not None else None
    if ref_w is None:
        ref_w = body_d
    if hips_pb is not None:
        fw, fd, fh, fbow, flift = HIPS_BOX
        w = ref_w * fw
        ob = body_widget(name, hips_pb, w, min(w * fd, body_d), w * fh, wgt_coll,
                         bow=w * fbow, lift=w * flift, segs=HIPS_SEGS)
        assign_shape(hips_pb, ob)

    prop_bones = set(n for n in extras if extras[n][2] == 'Props')
    apply_theme(rig, prop_bones)
    #props shouldnt spin with the body, they just ride along positionwise
    for n in prop_bones:
        if n in arm.bones:
            arm.bones[n].use_inherit_rotation = False
    hide_bare_bones(rig, prop_bones)
    patch_layers_ui(rig)

    for c in arm.collections_all:
        if c.name in ROWS:
            c['rigify_ui_row'] = ROWS[c.name][0]
            if ROWS[c.name][1]:
                c['rigify_color_set_id'] = ROWS[c.name][1]
            c.is_visible = not ('(FK)' in c.name or '(Tweak)' in c.name)
    phys_c.is_visible = False
    expr_c.is_visible = False
    # Alternative forms and weapons are optional, not part of the default body.
    props_c.is_visible = False
    rig.show_in_front = True
    for o in props:
        bind_props(o, segs)
        add_props_toggle(o, arm)
    for o in meshes:
        rename_groups(o)
        o.parent = rig
        o.matrix_parent_inverse = Matrix.Identity(4)
        mod = o.modifiers.new('Armature', 'ARMATURE')
        mod.object = rig
        idx = list(o.modifiers).index(mod)
        if idx > 0:
            o.modifiers.move(idx, 0)
    for e in empties:
        if e.name in bpy.data.objects and bpy.data.objects[e.name] == e:
            bpy.data.objects.remove(e, do_unlink=True)
    src_data = src.data
    bpy.data.objects.remove(src, do_unlink=True)
    if src_data.users == 0:
        bpy.data.armatures.remove(src_data)
    scene = bpy.context.scene
    master = bpy.data.collections.new(name + '_Master')
    scene.collection.children.link(master)
    rig['bangboo_character_collection'] = master
    c_rigs = bpy.data.collections.new(name + '_Rigs')
    c_mesh = bpy.data.collections.new(name + '_Mesh')
    for c in list(wgt_coll.users_collection if hasattr(wgt_coll, 'users_collection') else []):
        c.children.unlink(wgt_coll)
    for parent in [scene.collection] + list(bpy.data.collections):
        if parent != wgt_coll and wgt_coll.name in parent.children:
            parent.children.unlink(wgt_coll)
    master.children.link(wgt_coll)
    master.children.link(c_mesh)
    master.children.link(c_rigs)
    link_only(rig, c_rigs)
    for o in body + eyes:
        link_only(o, c_mesh)
    if props:
        c_props = bpy.data.collections.new(name + '_Props')
        master.children.link(c_props)
        for o in props:
            link_only(o, c_props)
    lw = find_layer(bpy.context.view_layer.layer_collection, wgt_coll)
    if lw:
        lw.exclude = True
    organize_bangboo_collections(rig)
    for collection_name in import_collections:
        collection = bpy.data.collections.get(collection_name)
        if collection and collection != scene.collection and not collection.objects and not collection.children:
            bpy.data.collections.remove(collection)
    activate(rig)
    return rig, slots


if __name__ == '__main__':
    rig, slots = run()
    print('Bangboo rig built:', rig.name, '| face slots:', ', '.join(slots))
